docstring:
Three-point transitivity theorem for the Möbius group PGL(2, ℂ):
for any three pairwise distinct projective points v₁, v₂, v₃ and any three pairwise distinct projective points w₁, w₂, w₃,
there exists a Möbius matrix M mapping v_i to w_i for i = 1, 2, 3.

goal_type:
∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {H : Type u_2} [inst_2 : TopologicalSpace H]
  (I : ModelWithCorners ℝ E H) {M : Type u_3} [inst_3 : MetricSpace M] [inst_4 : ChartedSpace H M]
  [inst_5 : IsManifold I (↑⊤) M] [inst_6 : CompactSpace M] [inst_7 : GromovCompactness.ClosedTameTarget I M] {k : ℕ}
  (th : GromovCompactness.Bubbling.TargetThresholds I M)
  (u_lim : GromovCompactness.Extensions.MarkedStableTreeLimit I k) (B : ℝ),
  GromovCompactness.Extensions.markedTreeTotalEnergy I u_lim ≤ B →
    let P := Fintype.card { v // GromovCompactness.Extensions.is_principal_component_marked I u_lim v };
    let G := Fintype.card { v // GromovCompactness.Extensions.is_ghost_component_marked I u_lim v };
    ↑P * th.h ≤ B ∧
      (1 < Fintype.card u_lim.tree.V → G ≤ P + k - 2) ∧ ↑(Fintype.card u_lim.tree.V) ≤ 1 ⊔ (2 * ⌊B / th.h⌋ + ↑k - 2)

